save() { git -C "$run/worktrees/$1" add -A && git -C "$run/worktrees/$1" diff --cached "$(cat $run/start-$1 2>/dev/null || echo $base)" -- . ':!**/__pycache__/**' > "$run/fixes/$1.patch" && git worktree remove --force "$run/worktrees/$1"; }
stack() { name=$1; shift; wt=$run/worktrees/$name; [ -d $wt ] || git worktree add -q --detach "$wt" "$base"; for p in "$@"; do git -C "$wt" apply --index "$run/fixes/$p.patch" || echo "FAIL $p"; done; c=$(git -C "$wt" commit-tree "$(git -C "$wt" write-tree)" -p "$base" -m "start $name"); git -C "$wt" reset -q --soft "$c"; echo $c > $run/start-$name; echo "$name starts at $c"; }
